window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f37eef247a285347"]={"versions": [{"id": "FIG-f37eef247a285347", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Einzelschritts innerhalb der AUTOSAR-E2E-Bibliothek (End-to-End Communication Protection Library, E2E Profile 7m). Das Diagramm detailliert das Verhalten der Prüffunktion <code>E2E_P07mCheck()</code> beim Auslesen des Nachrichtentyps (<code>MessageType</code>) für Client- und Serverseite.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Kontext-Element: Aktivitätsbereich bzw. aufrufende Funktion <code>E2E_P07mCheck()</code>.</li>\n<li>Eingangsdaten: Serialisiertes Datenarray <code>Data</code> an Byte-Position <code>[Offset+20]</code>.</li>\n<li>Lokale Variable / Zielentität: <code>ReceivedMessageType</code> vom Typ <code>uint8</code>.</li>\n<li>Steuerelemente: Anfangsknoten (Initial Node), ein Aktionsknoten (Action Node) und ein Endknoten (Activity Final Node).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Start am Initialknoten der Teilaktivität innerhalb von <code>E2E_P07mCheck()</code>.</li>\n<li>Übergang zum Aktionsknoten: Extrahieren des 2-Bit breiten Felds <code>MessageType</code> aus den Bits 0 und 1 des Bytes <code>Data[Offset+20]</code> in Big-Endian-Reihenfolge und Zuweisung an die lokale Variable <code>ReceivedMessageType</code> mittels der Operation <code>ReceivedMessageType = (Data[Offset+20] &amp; 0xC0) &gt;&gt; 6</code>.</li>\n<li>Übergang zum Aktivitätsendknoten und Abschluss des Ausleseschritts.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normativ bindend für Implementierungen von E2E Profile 7m Check (<code>E2E_P07mCheck()</code>) auf Client- und Serverseite gemäß PRS_E2E_00821.</li>\n<li>Bit-Maskierung und Shift: Die Bits 0 und 1 (bezogen auf MSB 0 der Big-Endian-Bitnummerierung) entsprechen den höchstwertigen Bits (0x80 und 0x40), daher Maskierung mit <code>0xC0</code> und Rechtsshift um 6 Bitpositionen.</li>\n<li>Zur Vermeidung von Pufferüberläufen ist vorab sicherzustellen, dass die Datenlänge mindestens <code>Offset + 21</code> Bytes umfasst.</li>\n</ul>"}, {"id": "FIG-a5363a6a6595e005", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Einzelschritts innerhalb der AUTOSAR-E2E-Bibliothek (End-to-End Communication Protection Library, E2E Profile 7m). Das Diagramm detailliert das Verhalten der Prüffunktion <code>E2E_P07mCheck()</code> beim Auslesen des Nachrichtentyps (<code>MessageType</code>) für Client- und Serverseite.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Kontext-Element: Aktivitätsbereich bzw. aufrufende Funktion <code>E2E_P07mCheck()</code>.</li>\n<li>Eingangsdaten: Serialisiertes Datenarray <code>Data</code> an Byte-Position <code>[Offset+20]</code>.</li>\n<li>Lokale Variable / Zielentität: <code>ReceivedMessageType</code> vom Typ <code>uint8</code>.</li>\n<li>Steuerelemente: Anfangsknoten (Initial Node), ein Aktionsknoten (Action Node) und ein Endknoten (Activity Final Node).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Start am Initialknoten der Teilaktivität innerhalb von <code>E2E_P07mCheck()</code>.</li>\n<li>Übergang zum Aktionsknoten: Extrahieren des 2-Bit breiten Felds <code>MessageType</code> aus den Bits 0 und 1 des Bytes <code>Data[Offset+20]</code> in Big-Endian-Reihenfolge und Zuweisung an die lokale Variable <code>ReceivedMessageType</code> mittels der Operation <code>ReceivedMessageType = (Data[Offset+20] &amp; 0xC0) &gt;&gt; 6</code>.</li>\n<li>Übergang zum Aktivitätsendknoten und Abschluss des Ausleseschritts.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normativ bindend für Implementierungen von E2E Profile 7m Check (<code>E2E_P07mCheck()</code>) auf Client- und Serverseite gemäß PRS_E2E_00821.</li>\n<li>Bit-Maskierung und Shift: Die Bits 0 und 1 (bezogen auf MSB 0 der Big-Endian-Bitnummerierung) entsprechen den höchstwertigen Bits (0x80 und 0x40), daher Maskierung mit <code>0xC0</code> und Rechtsshift um 6 Bitpositionen.</li>\n<li>Zur Vermeidung von Pufferüberläufen ist vorab sicherzustellen, dass die Datenlänge mindestens <code>Offset + 21</code> Bytes umfasst.</li>\n</ul>"}], "trans": [{"from": "FIG-f37eef247a285347", "to": "FIG-a5363a6a6595e005", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
